import { ownerRoutes,readInput,done,json,text,uuid,auditStatement,type Route } from '../door'
import { page,escape } from '../view'
import { Refusal } from '../upload'
import { people } from '../program/people'
import { documents,documentBytes } from './storage'
import { fieldKinds } from './review-model'
import { prepareReview,prepareQuestionnaireReview,correctReview,decideReview,reviewData,vendorObligations } from './review-storage'
const id=`(${uuid})`,both=(p:string)=>new RegExp(`^/(?:app|api)${p}$`)
const opts=(rows:{id:string;name:string}[])=>rows.map(p=>`<option value="${p.id}">${escape(p.name)}</option>`).join('')
export function vendorReviewHandler(clock:()=>Date) {
 const routes:Route[]=[
  {method:'POST',pattern:both(`/vendors/${id}/requests/${id}/reviews`),run:async(c,m)=>{const r=await prepareQuestionnaireReview(c.env,m[1],m[2],c.actor,c.now);return done(c,`/app/vendors/${m[1]}/document-reviews/${r.id}`,r,201)}},
  {method:'GET',pattern:both('/vendors/obligations'),run:async c=>{const rows=await vendorObligations(c.env);return c.isApi?json({obligations:rows}):page('Vendor control obligations',`<p>CUECs stay open until mapped to one of your controls. Accepting an unaddressed CUEC records the decision and keeps it open. Installation-wide obligations are separate from framework percentages.</p>${rows.map(r=>`<section><h2>${escape(r.vendor_name)}</h2><p>${escape(r.body)}</p><p>${r.control_id?`Mapped to <a href="/app/controls/${r.control_id}">${r.control_id}</a>`:`Open · ${r.accepted_unaddressed?'accepted as unaddressed':'unmapped'}`}</p><a href="/app/vendors/${r.vendor_id}/document-reviews/${r.review_id}">Approved cited review</a></section>`).join('')||'<p>No approved CUECs recorded.</p>'}`,200,{owner:c.actor.name,active:'vendors'})}},
  {method:'POST',pattern:both(`/vendors/${id}/review-settings`),run:async(c,m)=>{const input=await readInput(c.request),n=Number(text(input,'bridge_months',2));if(!Number.isInteger(n)||n<1||n>24)throw new Refusal('Bridge window must be 1 to 24 calendar months.');await c.env.DB.batch([c.env.DB.prepare('INSERT INTO vendor_review_settings(vendor_id,bridge_months) VALUES(?,?) ON CONFLICT(vendor_id) DO UPDATE SET bridge_months=excluded.bridge_months').bind(m[1],n),auditStatement(c.env,c.actor,'vendor.bridge-window','vendor:'+m[1],c.now,'succeeded',n+' calendar months')]);return done(c,'/app/vendors/'+m[1],{bridge_months:n})}},
  {method:'GET',pattern:both(`/vendors/${id}/documents/${id}/reviews`),run:async(c,m)=>{const doc=(await documents(c.env,m[1])).find(d=>d.id===m[2]);if(!doc)throw new Refusal('Document not found.',404);const rows=(await c.env.DB.prepare('SELECT id,revision,reason,proposed_at FROM vendor_document_reviews WHERE document_id=? ORDER BY revision').bind(m[2]).all()).results;return c.isApi?json({reviews:rows}):page('Cited document reviews',`<p>${escape(doc.filename)} · Original sha256 <code>${doc.sha256}</code></p><p>Local text extraction proposes fields with page citations. It never approves findings, alters tier or maps CUECs. Inspect every original page, including unextracted sections. Scanned or encrypted PDFs require a readable copy.</p><form method="post" action="/app/vendors/${m[1]}/documents/${m[2]}/reviews"><button>Prepare cited review</button></form><ul>${rows.map((r:any)=>`<li><a href="/app/vendors/${m[1]}/document-reviews/${r.id}">Revision ${r.revision}: ${escape(r.reason)}</a></li>`).join('')}</ul>`,200,{owner:c.actor.name,active:'vendors'})}},
  {method:'POST',pattern:both(`/vendors/${id}/documents/${id}/reviews`),run:async(c,m)=>{const r=await prepareReview(c.env,m[1],m[2],c.actor,c.now);return done(c,`/app/vendors/${m[1]}/document-reviews/${r.id}`,r,201)}},
  {method:'GET',pattern:both(`/vendors/${id}/document-reviews/${id}`),run:async(c,m)=>{
   const d=await reviewData(c.env,m[1],m[2],c.now);if(c.isApi)return json(d)
   const base=`/app/vendors/${m[1]}/document-reviews/${m[2]}`,controls=(await c.env.DB.prepare('SELECT id,name FROM controls ORDER BY name').all<{id:string;name:string}>()).results
   return page('Vendor document review',`<p>Revision ${d.review.revision} · ${d.decision?'Decision recorded':'Proposal only; no findings or mappings applied'}</p><p>Exact fingerprint <code>${d.review.snapshot_hash}</code></p><h2>Bridge-letter coverage</h2><p>${escape(d.bridge.state)} · ${escape(d.bridge.message)} · ${d.bridge.months} calendar months</p><h2>Extracted fields</h2>${d.snapshot.fields.map(f=>`<section><h3>${escape(f.kind)}</h3><p>${escape(f.value)}</p><blockquote>${escape(f.quote)}</blockquote><a href="/app/vendors/${m[1]}/document-reviews/${m[2]}/pages/${f.page}">Source page ${f.page}</a></section>`).join('')}<h2>Needs inspection</h2><ul>${d.snapshot.unresolved.map(x=>`<li>${escape(x)}</li>`).join('')}</ul><details><summary>All extracted pages</summary>${d.snapshot.pages.map((_,i)=>`<p><a href="${base}/pages/${i+1}">Page ${i+1}</a></p>`).join('')}</details>${d.decision?`<h2>${escape(String(d.decision.decision))}</h2><p>Named reviewer ${escape(String(d.decision.reviewer_name))} · ${escape(String(d.decision.reason))}</p>`:`<h2>Correct an extraction</h2><form method="post" action="${base}/correct"><input type="hidden" name="snapshot_hash" value="${d.review.snapshot_hash}"><label>Field<select name="field_id" aria-label="Field">${d.snapshot.fields.map(f=>`<option value="${f.id}">${escape(f.kind+': '+f.value.slice(0,70))}</option>`).join('')}${fieldKinds.map(k=>`<option value="new:${k}">Add omitted ${k}</option>`).join('')}</select></label><label>Corrected value<textarea name="value" required maxlength="4000"></textarea></label><label>Source page<input type="number" name="page" min="1" max="${d.snapshot.pages.length}" required></label><label>Exact source passage<textarea name="quote" required maxlength="4000"></textarea></label><label>Correction reason<input name="reason" maxlength="500" required></label><button>Retain corrected revision</button></form><h2>Decide this exact revision</h2><form method="post" action="${base}/decision"><input type="hidden" name="snapshot_hash" value="${d.review.snapshot_hash}"><label>Named reviewer<select name="reviewer_person_id" aria-label="Named reviewer" required><option value="">Select from People</option>${opts(await people(c.env))}</select></label>${d.snapshot.fields.filter(f=>f.kind==='cuec').map(f=>`<label>${escape(f.value)}<select name="mapping_${f.id}" aria-label="${escape(f.value)}"><option value="">Unmapped: keep obligation open</option><option value="unaddressed">Explicitly accept as unaddressed (still open)</option>${opts(controls)}</select></label>`).join('')}<label>Decision<select name="decision"><option value="approved">Approve findings, CUECs and proposed tier impact</option><option value="rejected">Reject; change nothing</option></select></label><label>Decision reason<input name="reason" maxlength="1000" required></label><button>Record exact decision</button></form>`}<h2>Proposal history</h2><ul>${d.history.map((r:any)=>`<li><a href="/app/vendors/${m[1]}/document-reviews/${r.id}">Revision ${r.revision}</a> · ${escape(r.reason)}</li>`).join('')}</ul><p><a href="/app/vendors/obligations">CUEC readiness obligations</a></p><p><a href="/app/vendors/${m[1]}">Vendor diligence</a></p>`,200,{owner:c.actor.name,active:'vendors'})
  }},
  {method:'POST',pattern:both(`/vendors/${id}/document-reviews/${id}/correct`),run:async(c,m)=>{const r=await correctReview(c.env,m[1],m[2],await readInput(c.request),c.actor,c.now);return done(c,`/app/vendors/${m[1]}/document-reviews/${r.id}`,r,201)}},
  {method:'POST',pattern:both(`/vendors/${id}/document-reviews/${id}/decision`),run:async(c,m)=>done(c,`/app/vendors/${m[1]}/document-reviews/${m[2]}`,await decideReview(c.env,m[1],m[2],await readInput(c.request),c.actor,c.now))},
  {method:'GET',pattern:both(`/vendors/${id}/document-reviews/${id}/pages/(\\d+)`),run:async(c,m)=>{const d=await reviewData(c.env,m[1],m[2],c.now),n=Number(m[3]);if(!d.snapshot.pages[n-1])throw new Refusal('Cited page not found.',404);const doc=(await documents(c.env,m[1])).find(x=>x.id===d.review.document_id);if(!doc||!await documentBytes(c.env,doc))throw new Refusal('Original bytes unavailable or changed.',409);await auditStatement(c.env,c.actor,'vendor.source-page','vendor:'+m[1],c.now,'succeeded','page '+n,{revision:doc.sha256}).run();return c.isApi?json({page:n,text:d.snapshot.pages[n-1],document_sha256:doc.sha256}):page('Original document page',`<h2>Page ${n} of ${d.snapshot.pages.length}</h2><p>Retained source text from original sha256 <code>${doc.sha256}</code>. PDF pages retain extracted text, without layout or images. A native questionnaire transcript has one source page per question and retains its exact JSON original.</p><pre>${escape(d.snapshot.pages[n-1])}</pre><p><a href="/app/vendors/${m[1]}/documents/${doc.id}/download${doc.media_type==='application/pdf'?'#page='+n:''}">${doc.media_type==='application/pdf'?'Download original PDF; page '+n:'Download original source transcript'}</a></p><a href="/app/vendors/${m[1]}/document-reviews/${m[2]}">Return to review</a>`,200,{owner:c.actor.name,active:'vendors'})}},
 ];return ownerRoutes(routes,clock)
}
